export type SettingsStackParamList = {
  SettingsHome: undefined;
  SettingsDetail: { id: string; title: string };
};

import type { LinkingOptions } from '@react-navigation/native';
import type { SettingsStackParamList } from './types';

export const linking: LinkingOptions<SettingsStackParamList> = {
  prefixes: ['myapp://'],
  config: {
    screens: {
      SettingsHome: 'settings',
      SettingsDetail: 'settings/detail/:id',
    },
  },
};

import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { SettingsScreen } from '../screens/SettingsScreen';
import { SettingsDetailScreen } from '../screens/SettingsDetailScreen';
import { linking } from './linking';
import type { SettingsStackParamList } from './types';

const Stack = createNativeStackNavigator<SettingsStackParamList>();

export function SettingsStack(): JSX.Element {
  return (
    <SafeAreaProvider>
      <NavigationContainer linking={linking}>
        <Stack.Navigator initialRouteName="SettingsHome">
          <Stack.Screen name="SettingsHome" component={SettingsScreen} />
          <Stack.Screen name="SettingsDetail" component={SettingsDetailScreen} />
        </Stack.Navigator>
      </NavigationContainer>
    </SafeAreaProvider>
  );
}

import type { NativeStackScreenProps } from '@react-navigation/native-stack';
import { Text, Pressable, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import type { SettingsStackParamList } from '../navigation/types';

type Props = NativeStackScreenProps<SettingsStackParamList, 'SettingsHome'>;

export function SettingsScreen({ navigation }: Props): JSX.Element {
  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Settings</Text>
      <Pressable accessibilityRole="button" accessibilityLabel="Open profile settings"
        onPress={() => navigation.navigate('SettingsDetail', { id: 'profile', title: 'Profile' })}>
        <Text>Profile settings</Text>
      </Pressable>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 24 },
  title: { fontSize: 20, fontWeight: '700' },
});

import type { NativeStackScreenProps } from '@react-navigation/native-stack';
import { Text, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import type { SettingsStackParamList } from '../navigation/types';

type Props = NativeStackScreenProps<SettingsStackParamList, 'SettingsDetail'>;

export function SettingsDetailScreen({ route }: Props): JSX.Element {
  const { id, title } = route.params;
  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>{title || 'Settings detail'}</Text>
      <Text>Settings for {id}</Text>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 24 },
  title: { fontSize: 20, fontWeight: '700' },
});
